import {compileSTM} from './stm32-compiler.js';
import {STM32_BOARDS} from './stm32-boards.js';
import {compileESP,ESP_CLANG_SHA256} from './esp-compiler.js';
let module;
self.onmessage=async({data})=>{try{
 if(!module){const url=new URL('./esp32/compiler/clang.wasm.gz',import.meta.url),storage=await caches.open('circuitforge-esp-clang-v3');let response=await storage.match(url);postMessage({progress:response?'Clang önbellekten hazırlanıyor':'Clang indiriliyor · ilk kullanımda 22.6 MB'});if(!response){response=await fetch(url);if(!response.ok)throw Error('ESP derleyicisi alınamadı.');}const compressed=await response.arrayBuffer();if(compressed.byteLength>24*1024*1024)throw Error('Derleyici paket boyutu aşıldı.');const bytes=await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(bytes.byteLength!==80735841)throw Error('Derleyici boyutu doğrulanamadı.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');if(hash!==ESP_CLANG_SHA256){await storage.delete(url);throw Error('Derleyici SHA-256 doğrulaması başarısız.');}try{await storage.put(url,new Response(compressed));}catch{postMessage({progress:'Cache dolu · derleyici oturum belleğinde hazır'});}postMessage({progress:'Clang hazırlanıyor'});module=await WebAssembly.compile(bytes);}
 postMessage({progress:(data.language==='c'?'C17':'C++')+' → gerçek '+(STM32_BOARDS[data.chip]?'ARM':'ESP')+' firmware'});const result=STM32_BOARDS[data.chip]?await compileSTM(module,data.source,data.chip,data.files||[],data.language||'c'):await compileESP(module,data.source,data.chip,data.files||[],data.language||'arduino');postMessage({ok:true,result},[result.image.buffer,result.elf.buffer]);
 }catch(error){postMessage({ok:false,error:error.message});}};
